3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	
14	/**
15	 * When a create request opts in via {@code sharesHousehold}, links the new owner into
16	 * the household of the existing same-lastName owner(s) at the same address by assigning
17	 * them all a shared {@code householdId}. Runs after {@link BuildOwner} (so the entity
18	 * exists) and before {@link SaveOwner} (so the new owner is persisted with the id).
19	 *
20	 * <p>The household is keyed on the normalized last name and address (the same
21	 * comparison {@link CheckOwnerHouseholdUnique} uses). If an existing housemate already
22	 * carries a {@code householdId} it is reused; otherwise a stable id is derived from the
23	 * household key and back-filled onto the existing housemates, so every member — the new
24	 * owner and each prior one — shares one identifier. A request that does not opt in is
25	 * left with a null {@code householdId}.
26	 */
27	public class AssignHousehold {
28	
29	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
30	            OwnerRepository ownerRepository) {
31	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            return;
33	        }
34	        String lastName = normalize(owner.getLastName());
35	        String address = normalize(owner.getAddress());
36	
37	        List<Owner> housemates = new ArrayList<>();
38	        String existingId = null;
39	        for (Owner existing : ownerRepository.findAll()) {
40	            if (lastName.equals(normalize(existing.getLastName()))
41	                    && address.equals(normalize(existing.getAddress()))) {
42	                housemates.add(existing);
43	                if (existingId == null && existing.getHouseholdId() != null) {
44	                    existingId = existing.getHouseholdId();
45	                }
46	            }
47	        }
48	
49	        String householdId = existingId != null ? existingId : deriveHouseholdId(lastName, address);
50	        owner.setHouseholdId(householdId);
51	        for (Owner mate : housemates) {
52	            if (!householdId.equals(mate.getHouseholdId())) {
53	                mate.setHouseholdId(householdId);
54	                ownerRepository.save(mate);
55	            }
56	        }
57	    }
58	
59	    /**
60	     * A stable identifier for a household, derived deterministically from its normalized
61	     * last name and address so the same household always yields the same id.
62	     */
63	    private static String deriveHouseholdId(String lastName, String address) {
64	        String key = lastName + "|" + address;
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                    .digest(key.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder sb = new StringBuilder("HH-");
69	            for (int i = 0; i < 8; i++) {
70	                sb.append(String.format("%02X", digest[i]));
71	            }
72	            return sb.toString();
73	        }
74	        catch (NoSuchAlgorithmException e) {
75	            throw new IllegalStateException("SHA-256 not available", e);
76	        }
77	    }
78	
79	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
80	    private static String normalize(String value) {
81	        if (value == null) {
82	            return "";
83	        }
84	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
85	    }
86	}
